const now = Date.now();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  // Reminders count from the offboarding start (anchor_at), falling back to
  // checklist creation for rows written before anchor_at existed.
  const anchorRaw = r.anchor_at || r.created_at;
  const anchor = Date.parse(anchorRaw);
  if (!anchor) { continue; }
  const hours = (now - anchor) / 3600000;
  if (hours < 6) { continue; }
  const marks = [
    { m: 6, sent: r.sent_6h === true },
    { m: 12, sent: r.sent_12h === true },
    { m: 24, sent: r.sent_24h === true },
    { m: 48, sent: r.sent_48h === true }
  ];
  let due = 0;
  for (let k = 0; k < marks.length; k++) {
    if (hours >= marks[k].m && !marks[k].sent) { due = marks[k].m; }
  }
  if (!due) { continue; }
  out.push({ json: { rowId: r.id, milestone: due, hoursElapsed: Math.round(hours * 10) / 10, anchorAt: anchorRaw, personName: r.person_name, personEmail: r.person_email, offboardingStart: r.last_day, fileId: r.file_id, fileUrl: r.file_url, worksheetName: r.worksheet_name || 'Base tool checklist', createdAt: r.created_at, sent6: r.sent_6h === true || due >= 6, sent12: r.sent_12h === true || due >= 12, sent24: r.sent_24h === true || due >= 24, sent48: r.sent_48h === true || due >= 48, excludedOwners: r.excluded_owners || '' } });
}
return out;

const SUMMARY_RECIPIENTS = ['antonio.marusic@efuturemedia.com', 'raul@efuturemedia.com'];

const rec = $('Loop offboardings').first().json;
const sheet = $input.first().json;
const values = sheet && sheet.values ? sheet.values : [];

// Free-text notes maintained by Antonio in the offboarding_settings data table.
let closingNotes = '';
try { closingNotes = $('Normalise closing notes').first().json.notes || ''; } catch (e) { closingNotes = ''; }
const notesBlock = closingNotes ? '\n\n---\n' + closingNotes : '';

function cell(row, idx) {
  const v = row && row.length > idx ? row[idx] : '';
  return v === null || v === undefined ? '' : String(v).trim();
}

const outstanding = [];
for (let i = 1; i < values.length; i++) {
  const tool = cell(values[i], 0);
  if (!tool) { continue; }
  const status = cell(values[i], 4);
  if (!status) { continue; }
  const norm = status.toLowerCase();
  if (norm === 'done' || norm === 'not needed') { continue; }
  outstanding.push({ tool: tool, ownerConfluence: cell(values[i], 2), assignee: cell(values[i], 3), status: status });
}

const label = rec.milestone + 'h';
const header = '*' + rec.personName + '* (' + rec.personEmail + ') - offboarding checklist, ' + label + ' reminder\nChecklist: ' + rec.fileUrl + '\n';
const actions = [];

if (outstanding.length === 0) {
  let text = '*' + rec.personName + '* (' + rec.personEmail + ') - offboarding checklist is fully cleared.\n';
  text += 'Every tool is marked Done or Not needed. No further reminders will be sent.\n' + rec.fileUrl;
  text += notesBlock;
  for (let i = 0; i < SUMMARY_RECIPIENTS.length; i++) {
    actions.push({ json: { send: true, kind: 'cleared', email: SUMMARY_RECIPIENTS[i], text: text, rowId: rec.rowId, state: 'closed', sent6: rec.sent6, sent12: rec.sent12, sent24: rec.sent24, sent48: rec.sent48 } });
  }
  return actions;
}

const byAssignee = {};
const unassigned = [];
for (let i = 0; i < outstanding.length; i++) {
  const o = outstanding[i];
  if (!o.assignee) { unassigned.push(o); continue; }
  if (!byAssignee[o.assignee]) { byAssignee[o.assignee] = []; }
  byAssignee[o.assignee].push(o);
}

const emails = Object.keys(byAssignee);
for (let i = 0; i < emails.length; i++) {
  const email = emails[i];
  const tools = byAssignee[email];
  let text = header + '\n' + tools.length + ' tool(s) are still marked *To do* for you:\n';
  for (let t = 0; t < tools.length; t++) { text += '- ' + tools[t].tool + '\n'; }
  text += '\nPlease remove their access where needed, then set each row to *Done* or *Not needed*.';
  actions.push({ json: { send: true, kind: 'reminder', email: email, text: text, rowId: rec.rowId, state: 'open', sent6: rec.sent6, sent12: rec.sent12, sent24: rec.sent24, sent48: rec.sent48 } });
}

if (rec.milestone === 48) {
  let sum = '*48h summary - ' + rec.personName + '* (' + rec.personEmail + ')\n';
  sum += 'Offboarding can start: ' + (rec.offboardingStart || 'not recorded') + '\nChecklist: ' + rec.fileUrl + '\n\n';
  sum += outstanding.length + ' tool(s) were still not cleared 48h after the offboarding start:\n\n';
  for (let i = 0; i < emails.length; i++) {
    sum += '*' + emails[i] + '*\n';
    const tools = byAssignee[emails[i]];
    for (let t = 0; t < tools.length; t++) { sum += '- ' + tools[t].tool + ' (' + tools[t].status + ')\n'; }
    sum += '\n';
  }
  if (unassigned.length > 0) {
    sum += '*Nobody assigned* (no owner on Confluence, or excluded on the form)\n';
    for (let t = 0; t < unassigned.length; t++) { sum += '- ' + unassigned[t].tool + ' (owner on Confluence: ' + (unassigned[t].ownerConfluence || 'none') + ')\n'; }
    sum += '\n';
  }
  if (rec.excludedOwners) { sum += 'Owners excluded at intake: ' + rec.excludedOwners + '\n'; }
  sum += '\nReminders stop here - this offboarding is now closed in the register.';
  sum += notesBlock;
  for (let i = 0; i < SUMMARY_RECIPIENTS.length; i++) {
    actions.push({ json: { send: true, kind: 'summary', email: SUMMARY_RECIPIENTS[i], text: sum, rowId: rec.rowId, state: 'closed', sent6: rec.sent6, sent12: rec.sent12, sent24: rec.sent24, sent48: rec.sent48 } });
  }
}

if (actions.length === 0) {
  actions.push({ json: { send: false, kind: 'nothing-to-send', email: '', text: '', rowId: rec.rowId, state: rec.milestone === 48 ? 'closed' : 'open', sent6: rec.sent6, sent12: rec.sent12, sent24: rec.sent24, sent48: rec.sent48 } });
}
return actions;

// Always emits exactly one item, so an empty or broken settings table can never
// stop the reminder run.
let notes = '';
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  if (r && r.setting_key === 'closing_dm_notes' && r.setting_value) {
    notes = String(r.setting_value);
    break;
  }
}
// Let a literal \n typed in the data table UI act as a real line break.
notes = notes.split('\\n').join('\n').trim();
return [{ json: { notes: notes, hasNotes: notes.length > 0 } }];

